#include <iostream>
#include <string>

int main()
{
    std::string line;
    std::getline(std::cin, line);

    int letters{};
    int digits{};
    int other{};
    std::string up;

    for (char c : line)
    {
        if (c >= 'a' && c <= 'z')
        {
            ++letters;
            up.push_back(static_cast<char>(c - 'a' + 'A'));
        }
        else if (c >= 'A' && c <= 'Z')
        {
            ++letters;
            up.push_back(c);
        }
        else
        {
            if (c >= '0' && c <= '9') ++digits;
            else                      ++other;
            up.push_back(c);
        }
    }

    std::cout << "letters " << letters << "\n";
    std::cout << "digits " << digits << "\n";
    std::cout << "other " << other << "\n";
    std::cout << "upper [" << up << "]\n";

    return 0;
}
